import{_ as a,o as i,c as t,a2 as s}from"./chunks/framework.B7CclTRW.js";const m=JSON.parse('{"title":"版本与兼容说明","description":"","frontmatter":{},"headers":[],"relativePath":"guide/compatibility.md","filePath":"guide/compatibility.md"}'),l={name:"guide/compatibility.md"};function o(r,e,d,h,n,c){return i(),t("div",null,[...e[0]||(e[0]=[s('<h1 id="版本与兼容说明" tabindex="-1">版本与兼容说明 <a class="header-anchor" href="#版本与兼容说明" aria-label="Permalink to &quot;版本与兼容说明&quot;">​</a></h1><p>用 npmjs 上的公开包安装 ASAM UI。当前版本及安装命令以下表和接入指南为准。</p><h2 id="published-packages" tabindex="-1">npmjs 公开包 <a class="header-anchor" href="#published-packages" aria-label="Permalink to &quot;npmjs 公开包 {#published-packages}&quot;">​</a></h2><p>Pro <code>2.0.1</code>、芋道适配器 <code>2.0.1</code> 和平台适配包 <code>2.0.2</code> 都声明 UI <code>2.0.1</code> 为精确 peer。文档 MCP <code>1.0.1</code> 的内置基础组件资料快照仍为 UI <code>1.0.0</code>。地图模板通过官网完整工程提供，npmjs 暂无公开包。</p><h2 id="recommended" tabindex="-1">推荐安装组合 <a class="header-anchor" href="#recommended" aria-label="Permalink to &quot;推荐安装组合 {#recommended}&quot;">​</a></h2><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;!</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">--</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> stable-install-command</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span></span></code></pre></div><p>需要 Pro 时按 <a href="/pro/installation.html">Pro 快速开始</a> 安装配对版本。独立图标和芋道适配器按需安装，见 <a href="/guide/installation.html">安装与接入</a>。</p><h2 id="website-packages" tabindex="-1">本次官网构建使用的包 <a class="header-anchor" href="#website-packages" aria-label="Permalink to &quot;本次官网构建使用的包 {#website-packages}&quot;">​</a></h2><p>这里记录预览与下载工程的构建输入。复现下载工程时保留随工程提供的清单和锁文件。标为“按需”的 peer 只在使用相应能力时需要安装。</p><h2 id="verified" tabindex="-1">支持范围 <a class="header-anchor" href="#verified" aria-label="Permalink to &quot;支持范围 {#verified}&quot;">​</a></h2><p>UI 和 Pro 支持 Vue <code>&gt;=3.5.34 &lt;3.6.0</code>，Element Plus 锁定 <code>2.14.7</code>。Vue Router 与自动导入插件按需使用。使用其他受支持的 Vue 版本或构建工具时，在目标工程验证。</p><h2 id="related" tabindex="-1">对应文档 <a class="header-anchor" href="#related" aria-label="Permalink to &quot;对应文档 {#related}&quot;">​</a></h2><ul><li><a href="/component-catalog.html">基础组件</a>与 <a href="/guide/ui-changelog.html">UI 更新日志</a></li><li><a href="/pro/components.html">Pro 高级组件</a>、<a href="/pro/templates.html">页面模板</a>与 <a href="/guide/pro-changelog.html">Pro 更新日志</a></li><li><a href="/guide/upgrade.html">升级指南</a>与 <a href="/ai/mcp.html">MCP 接入</a></li></ul>',13)])])}const u=a(l,[["render",o]]);export{m as __pageData,u as default};
